n("דברת", "דברת היא עיר עתיקה בגליל, על גבול נחלת זבולון, שמוזכרת בספר יהושע. היום יש בגליל התחתון כפר ומושב שנושאים שם דומה. השם קרוב לשם דבורה, והוא ניתן לבנות. הוא נדיר מאוד, ונשמע עתיק ומיוחד.", ["דבורה", "דבורית"])
n("יחיעם", "יחיעם הוא שם עברי חדש שבנוי מהמילים יחי ועם, ופירושו יחיה העם. השם נולד בתקופה של התחייה הלאומית. יחיעם הוא גם שם של קיבוץ בגליל המערבי, ליד מבצר צלבני עתיק. השם ניתן לבנים, והוא נדיר.", ["עמי"])
n("סלעית", "סלעית היא ציפור שיר קטנה שחיה בין סלעים במדבר ובהרים. השם עברי, והוא קשור גם למילה סלע. השם ניתן לבנות, והוא נדיר. הוא שייך לקבוצה של שמות מעולם הטבע, כמו סלע וצופית.", ["סלע", "צופית"])
n("שרלוט", "שרלוט היא הצורה הנשית הצרפתית של שארל, שם גרמני שפירושו אדם חופשי. השם נפוץ מאוד באנגליה ובצרפת, והוא היה שמן של מלכות ונסיכות. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("סרג'יו", "סרג׳יו הוא שם איטלקי וספרדי שבא מהשם הרומי סרגיוס, שם של משפחה רומית עתיקה. השם נפוץ באיטליה, בספרד ובאמריקה הלטינית, וברוסית מוכרת הצורה סרגיי. בארץ הוא נדיר, והוא ניתן לבנים.", [])
n("גאן", "גאן הוא שם חדש ונדיר, ואולי הוא בא מהמילה גאון, גדולה וחוכמה. בשפות אחרות יש שמות דומים בצליל, כמו גן ביפנית. השם ניתן לבנים, והוא קצר ופשוט.", [])
n("גניפר", "גניפר היא כתיב של ג׳ניפר, שם אנגלי ממקור ולשי שפירושו לבנה וטהורה. השם קשור לגווינבר, אשתו של המלך ארתור באגדות. באמריקה השם היה נפוץ מאוד בשנות השבעים והשמונים. השם ניתן לבנות, והוא נדיר בארץ.", [])
n("ליבת", "ליבת הוא שם עברי חדש מהמילה לב. השם נשמע רך ואוהב, וקרובים אליו השמות ליבי וליבה. השם ניתן לבנות, והוא נדיר. יש בו תחושה של ילדה שהיא הלב של המשפחה.", ["ליבי", "ליבה"])
n("חסידה", "חסידה היא ציפור נודדת גדולה, שעוברת מעל הארץ פעמיים בשנה. בספר ירמיהו נאמר שהחסידה בשמים יודעת את מועדיה. במסורת השם קשור למילה חסד. השם ניתן לבנות, והוא נדיר.", [])
n("סווטלנה", "סווטלנה הוא כתיב של סבטלנה, שם רוסי שבא מהמילה סווט, אור, ופירושו מאירה. השם היה נפוץ מאוד בברית המועצות. בארץ השם הגיע עם העלייה, והוא ניתן לבנות.", ["סבטלנה"])
n("נירן", "נירן הוא שם עברי חדש שבנוי מהמילים ניר ורן, ופירושו השדה שר. נירן הוא גם שם של יישוב בבקעת הירדן. השם ניתן לבנים, והוא נדיר. קרובים אליו השמות ניר ורן.", ["ניר", "רן"])
n("זיוית", "זיוית הוא שם עברי מהמילה זיו, אור וברק. מאותה מילה באים גם השמות זיו וזיוה. השם ניתן לבנות, והוא נדיר. בגאומטריה זווית היא מילה אחרת, אבל הצליל דומה.", ["זיו", "זיוה"])
n("נעמן", "נעמן הוא שם מקראי מהמילה נועם. בספר מלכים נעמן הוא שר צבא ארם, שחלה בצרעת ונרפא אחרי שטבל בירדן לפי דברי אלישע. השם ניתן לבנים, והוא נדיר. נעמן הוא גם שם של נחל בגליל.", ["נועם"])
n("גני", "גני הוא שם עברי שפירושו הגן שלי. השם נשמע רך וטבעי, וקרובים אליו השמות גנית וגניה. השם ניתן לבנות, והוא נדיר. יש בו תמונה של צמחים ושל פריחה.", ["גנית", "גניה"])
n("ג'יין", "ג׳יין היא צורה אנגלית של יוחנה, הצורה הנשית של יוחנן, ה׳ חנן. השם היה נפוץ מאוד באנגליה, והוא מוכר בזכות הסופרת ג׳יין אוסטן. בארץ השם נדיר, והוא ניתן לבנות.", ["ג'ון"])
n("ויטל", "ויטל הוא שם ספרדי שבא מהמילה הלטינית ויטה, חיים. השם היה נפוץ בקהילות של יהודי ספרד, לפעמים כתרגום של השם חיים. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", ["חיים", "ויטלי"])
n("יפעה", "יפעה הוא שם עברי מהמילה יפעה, זוהר ויופי. מאותו שורש בא גם השם יפעת. השם ניתן לבנות, והוא נדיר. יש בו אור ויופי, והוא נשמע עתיק ורך.", ["יפעת"])
n("גתית", "גתית הוא כתיב של גיתית, שם של כלי נגינה עתיק, וגם מלשון גת, המקום שבו דורכים ענבים. גתית היא גם שם של מושב בגליל. השם ניתן לבנות, והוא נדיר.", ["גיתית", "גת"])
n("אספה", "אספה הוא שם עברי נדיר מהמילה אסיפה, התכנסות של אנשים. מאותו שורש באים גם השמות אסף ואסיף. השם ניתן לבנים, והוא נשמע עתיק ומיוחד.", ["אסף", "אסיף"])
n("אביחיל", "אביחיל הוא שם מקראי שבנוי מהמילים אבי וחיל, ופירושו אבי הוא כוח. בספר במדבר צוריאל בן אביחיל הוא נשיא משפחות מררי. בספר אסתר אביחיל הוא אביה של אסתר. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", [])
n("צפניה", "צפניה הוא אחד מתרי עשר הנביאים, וספר צפניה פותח בדברי ה׳ אליו בימי יאשיהו המלך. השם פירושו ה׳ צפן, שמר והגן. השם ניתן לבנים, והוא נדיר. קרוב אליו השם צפנת.", ["צפנת"])
n("בוני", "בוני הוא שם אנגלי שבא מהמילה הסקוטית בוני, יפה. השם היה נפוץ באמריקה באמצע המאה העשרים. בעברית השם נשמע גם כמו בוני, מי שבונה. השם ניתן לבנות, והוא נדיר בארץ.", [])
n("ליבנה", "ליבנה הוא עץ עם גזע לבן שגדל בארצות קרות. השם קשור למילה לבן, ויש לו גם שורש עתיק כשם של מקום. השם ניתן גם לבנים וגם לבנות, והוא נדיר. קרוב אליו השם לבנה.", ["לבנה"])
n("דימה", "דימה הוא צורת חיבה רוסית של דמיטרי, שם יווני שקשור לדמטר, אלת האדמה והיבול. השם נפוץ ברוסיה ובאוקראינה. בארץ השם הגיע עם העלייה, והוא ניתן לבנים.", [])
n("ויולטה", "ויולטה היא המילה האיטלקית והספרדית לסיגלית, הפרח הסגול. השם מוכר מהאופרה לה טרוויאטה, שבה ויולטה היא הגיבורה. בארץ השם נדיר, והוא ניתן לבנות.", ["ויולט", "סיגלית"])
n("אגנס", "אגנס הוא שם בינלאומי שבא מהמילה היוונית הגנה, טהורה. השם היה נפוץ באירופה בימי הביניים, והוא חוזר להיות אופנתי. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("יגיל", "יגיל הוא שם עברי מהמילה גיל, שמחה, ופירושו ישמח. השם נשמע כמו ברכה לילד שיהיה שמח. השם ניתן לבנים, והוא נדיר. קרובים אליו השמות יגל וגיל.", ["יגל", "גיל"])
n("תרזה", "תרזה הוא שם בינלאומי ממקור יווני, ויש שקושרים אותו למילה קציר. השם נפוץ באיטליה, בספרד ובפולין. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("עשירה", "עשירה הוא שם עברי מהמילה עשיר, מלא שפע. השם נשמע כמו ברכה לחיים מלאים. השם ניתן לבנות, והוא נדיר מאוד. קרוב אליו בצליל השם אשירה, מלשון שירה.", ["אשירה"])
n("מושית", "מושית הוא שם נדיר, וכנראה הוא צורה נשית של משה, שבא מהשורש מ־ש־ה, משייה מהמים. השם נשמע עברי ושונה. השם ניתן לבנות, והוא נדיר מאוד.", ["משה"])
n("קלריס", "קלריס היא צורה צרפתית של קלרה, שם לטיני שפירושו בהירה. השם היה נפוץ בצרפת ובצפון אפריקה. בארץ השם נדיר, והוא ניתן לבנות.", ["קלרה", "קלייר"])
n("רשף", "רשף הוא שם עברי מהמילה רשף, ניצוץ של אש או ברק. השם נשמע חזק ומהיר. השם ניתן לבנים, והוא נדיר. רשף הוא גם שם של מושב בשרון.", [])
n("מגלי", "מגלי הוא שם נדיר, וכנראה הוא צורת חיבה של מגדלנה, שם שבא מהעיר מגדל שעל חוף הכנרת. בפולנית מגדה ומגלי הם שמות מוכרים. השם ניתן לבנות.", ["מגדלנה"])
n("לוסיאנה", "לוסיאנה הוא שם שבא מהמילה הלטינית לוקס, אור. השם נפוץ בשפה הספרדית, באיטלקית ובפורטוגזית. בארץ השם נדיר, והוא ניתן לבנות.", ["לוסי"])
n("צמרת", "צמרת היא ראש העץ, החלק הגבוה ביותר. השם עברי, והוא נשמע גבוה וירוק. הוא ניתן לבנות, והוא נדיר. בעברית צמרת היא גם מילה לקבוצה המובילה, הטובים ביותר.", [])
n("חוליו", "חוליו הוא הצורה הספרדית של יוליוס, שם רומי עתיק. השם נפוץ בספרד ובאמריקה הלטינית, והוא מוכר בזכות זמרים ידועים. בארץ השם נדיר, והוא ניתן לבנים.", [])
n("דייגו", "דייגו הוא כתיב של דיאגו, שם ספרדי שבא כנראה מהשם סנטיאגו, צורה של יעקב. השם נפוץ בספרד ובאמריקה הלטינית. בארץ הוא נדיר, והוא ניתן לבנים.", ["דיאגו", "יעקב"])
n("גסיקה", "גסיקה הוא כתיב של ג׳סיקה, שם שנעשה מוכר באנגלית בזכות מחזה של שייקספיר. יש שקושרים אותו לשם העברי יסכה. השם ניתן לבנות, והכתיב הזה נדיר בארץ.", ["ג'סיקה"])
n("פועה", "פועה היא אחת משתי המיילדות במצרים, יחד עם שפרה. בספר שמות מסופר שהן לא צייתו לפרעה, והצילו את התינוקות של העברים. השם ניתן לבנות, והוא נדיר, אבל מביע אומץ.", ["שפרה"])
n("לילית", "לילית הוא שם עברי מהמילה לילה. במסורת לילית היא גם דמות מהאגדות. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות לילה ולילי.", ["לילה", "לילי"])
n("תמנע", "תמנע הוא שם מקראי. בספר בראשית תמנע היא פילגש של אליפז בן עשו, ותמנה היא גם עיר שבה ביקר שמשון. היום עמק תמנע בערבה מוכר בזכות מכרות הנחושת העתיקים. השם ניתן לבנות.", [])
n("ניצנה", "ניצנה הוא שם עברי מהמילה ניצן, פרח שעוד לא נפתח. ניצנה היא גם שם של יישוב בנגב, ליד גבול מצרים. השם ניתן לבנות, והוא נדיר. קרוב אליו השם ניצן.", ["ניצן"])
n("שיקמה", "שיקמה הוא כתיב של שקמה, עץ גדול ורחב שגדל בשפלה ובמישור החוף. השם ניתן לבנות, והוא נדיר. שיקמה הוא גם שם של נחל בדרום.", ["שקמה"])
n("ארזה", "ארזה הוא שם עברי מהמילה ארז, עץ גבוה וחזק. מאותה מילה בא גם השם ארז. השם ניתן לבנות, והוא נדיר. ארזה היא גם שם של מקום ליד מוצא, במבואות ירושלים.", ["ארז"])
n("צרלס", "צרלס הוא כתיב של צ׳רלס, שם גרמני שפירושו אדם חופשי. השם נפוץ באנגליה, והוא היה שמם של כמה מלכים. השם ניתן לבנים, והכתיב הזה נדיר בארץ.", [])
n("זכאי", "זכאי הוא שם עברי מהמילה זכאי, צודק וטהור. השם מוכר בזכות רבן יוחנן בן זכאי, שהקים את מרכז הלימוד ביבנה אחרי חורבן בית שני. השם ניתן לבנים, והוא נדיר.", [])
n("הרצליה", "הרצליה היא עיר בשרון שנקראה על שם בנימין זאב הרצל, חוזה מדינת היהודים. השם ניתן לבנות, והוא היה מוכר בשנים שאחרי קום המדינה. היום הוא נדיר מאוד.", ["הרצל"])
n("קרל", "קרל הוא שם גרמני שפירושו אדם חופשי. השם נפוץ בגרמנית ובשפות הצפון, והוא היה שמם של קיסרים ומלכים. בארץ השם נדיר, והוא ניתן לבנים. קרובה אליו צורת הנקבה קרלה.", ["קרלה"])
n("לירית", "לירית הוא שם עברי חדש מהמילה לירה, כלי נגינה עתיק, ומשירה לירית. השם נשמע מוזיקלי ורך. השם ניתן לבנות, וקרובים אליו השמות ליר ולירי.", ["ליר", "לירי"])
n("מרגנית", "מרגנית היא פרח בר קטן ואדום, שפורח בשדות בחורף ובאביב. השם עברי, והוא היה נפוץ בארץ בשנות החמישים. מרגנית היא גם שם של מושב בגליל. השם ניתן לבנות.", ["כלנית"])
n("סתוית", "סתוית היא פרח שפורח בסתיו, עם עלים ורודים עדינים. השם עברי, והוא קשור לסתיו, העונה. השם ניתן לבנות, והוא נדיר. קרוב אליו השם סתיו.", ["סתיו"])
n("יקי", "יקי הוא צורת חיבה של יעקב, אחד משלושת האבות. השם יעקב קשור למילה עקב. יקי היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנים.", ["יעקב"])
n("מריאנו", "מריאנו הוא שם ספרדי ואיטלקי שבא מהשם הרומי מריוס, ויש שקושרים אותו לשם מריה. השם נפוץ בספרד ובאמריקה הלטינית. בארץ השם נדיר, והוא ניתן לבנים.", ["מריאנה"])
